lemma ZMod.plus_ge_mult [h: NeZero n] [h': GtTwo n] {x y : ZMod n}
  (hx : x.val ≤ 1) (hy : y.val ≤ 1) :
  (x * y).val ≤ (x + y).val

lemma or_val [h: NeZero n] [h': GtTwo n] {x y : ZMod n}
  (hx : x.val ≤ 1) (hy : y.val ≤ 1) :
  (x + y - x*y).val = ((x.val + y.val) - (x.val * y.val)) % n
